# Pending Raksa x Hitung Barang (label QR sekali pakai).
#  - Saat barang diberikan dari gudang: scan label QR (kamera / scanner / ketik kode).
#    Jumlah & penghitung terisi otomatis dari label; label langsung "dipakai" di server BM.
#    Tanpa label (stok lama) tetap boleh: isi jumlah manual (ditandai MANUAL).
#  - Saat picker menghitung: scan ulang label (verifikasi ke-2); bila >1 pack, hitung per pack.
#    Selisih per pack jatuh ke penghitung label pack itu (denda per pack).
#  - Hasil hitung picker dikirim ke laporan Hitung Barang.
# Label TIDAK mengubah stok; pergerakan stok tetap seperti sebelumnya (total label vs total hitung).
import sys
p = sys.argv[1] if len(sys.argv) > 1 else "web/dist/app.js"
s = open(p, encoding="utf-8").read()
if "rkLabelQrV1" in s:
    print("sudah"); sys.exit(0)

def R(a, b, n=1):
    global s
    c = s.count(a)
    assert c == n, (c, a[:90])
    s = s.replace(a, b)

